      function write_BIFF2Cell(out, r, c) {
        if (!out) out = new_buf(7);
        out.write_shift(2, r);
        out.write_shift(2, c);
        out.write_shift(2, 0);
        out.write_shift(1, 0);
        return out;
      }

      function write_BIFF2BERR(r, c, val, t) {
        var out = new_buf(9);
        write_BIFF2Cell(out, r, c);

        if (t == 'e') {
          out.write_shift(1, val);
          out.write_shift(1, 1);
        } else {
          out.write_shift(1, val ? 1 : 0);
          out.write_shift(1, 0);
        }

        return out;
      }
      /* TODO: codepage, large strings */


      function write_BIFF2LABEL(r, c, val) {
        var out = new_buf(8 + 2 * val.length);
        write_BIFF2Cell(out, r, c);
        out.write_shift(1, val.length);
        out.write_shift(val.length, val, 'sbcs');
        return out.l < out.length ? out.slice(0, out.l) : out;
      }

      function write_ws_biff2_cell(ba, cell, R, C) {
        if (cell.v != null) switch (cell.t) {
          case 'd':
          case 'n':
            var v = cell.t == 'd' ? datenum(parseDate(cell.v)) : cell.v;
            if (v == (v | 0) && v >= 0 && v < 65536) write_biff_rec(ba, 0x0002, write_BIFF2INT(R, C, v));else write_biff_rec(ba, 0x0003, write_BIFF2NUM(R, C, v));
            return;

          case 'b':
          case 'e':
            write_biff_rec(ba, 0x0005, write_BIFF2BERR(R, C, cell.v, cell.t));
            return;

          /* TODO: codepage, sst */

          case 's':
          case 'str':
            write_biff_rec(ba, 0x0004, write_BIFF2LABEL(R, C, cell.v));
            return;
        }
        write_biff_rec(ba, 0x0001, write_BIFF2Cell(null, R, C));
      }

      function write_ws_biff2(ba, ws, idx, opts) {
        var dense = Array.isArray(ws);
        var range = safe_decode_range(ws['!ref'] || "A1"),
            ref,
            rr = "",
            cols = [];

        if (range.e.c > 0xFF || range.e.r > 0x3FFF) {
          if (opts.WTF) throw new Error("Range " + (ws['!ref'] || "A1") + " exceeds format limit A1:IV16384");
          range.e.c = Math.min(range.e.c, 0xFF);
          range.e.r = Math.min(range.e.c, 0x3FFF);
          ref = encode_range(range);
        }

        for (var R = range.s.r; R <= range.e.r; ++R) {
          rr = encode_row(R);

          for (var C = range.s.c; C <= range.e.c; ++C) {
            if (R === range.s.r) cols[C] = encode_col(C);
            ref = cols[C] + rr;
            var cell = dense ? (ws[R] || [])[C] : ws[ref];
            if (!cell) continue;
            /* write cell */

            write_ws_biff2_cell(ba, cell, R, C, opts);
          }
        }
      }
      /* Based on test files */


      function write_biff2_buf(wb, opts) {
        var o = opts || {};
        if (DENSE != null && o.dense == null) o.dense = DENSE;
        var ba = buf_array();
        var idx = 0;

        for (var i = 0; i < wb.SheetNames.length; ++i) {
          if (wb.SheetNames[i] == o.sheet) idx = i;
        }

        if (idx == 0 && !!o.sheet && wb.SheetNames[0] != o.sheet) throw new Error("Sheet not found: " + o.sheet);
        write_biff_rec(ba, 0x0009, write_BOF(wb, 0x10, o));
        /* ... */

        write_ws_biff2(ba, wb.Sheets[wb.SheetNames[idx]], idx, o, wb);
        /* ... */

        write_biff_rec(ba, 0x000A);
        return ba.end();
      }

      function write_FONTS_biff8(ba, data, opts) {
        write_biff_rec(ba, "Font", write_Font({
          sz: 12,
          color: {
            theme: 1
          },
          name: "Arial",
          family: 2,
          scheme: "minor"
        }, opts));
      }

      function write_FMTS_biff8(ba, NF, opts) {
        if (!NF) return;
        [[5, 8], [23, 26], [41, 44], [
        /*63*/
        50,
        /*66],[164,*/
        392]].forEach(function (r) {
          for (var i = r[0]; i <= r[1]; ++i) {
            if (NF[i] != null) write_biff_rec(ba, "Format", write_Format(i, NF[i], opts));
          }
        });
      }

      function write_FEAT(ba, ws) {
        /* [MS-XLS] 2.4.112 */
        var o = new_buf(19);
        o.write_shift(4, 0x867);
        o.write_shift(4, 0);
        o.write_shift(4, 0);
        o.write_shift(2, 3);
        o.write_shift(1, 1);
        o.write_shift(4, 0);
        write_biff_rec(ba, "FeatHdr", o);
        /* [MS-XLS] 2.4.111 */

        o = new_buf(39);
        o.write_shift(4, 0x868);
        o.write_shift(4, 0);
        o.write_shift(4, 0);
        o.write_shift(2, 3);
        o.write_shift(1, 0);
        o.write_shift(4, 0);
        o.write_shift(2, 1);
        o.write_shift(4, 4);
        o.write_shift(2, 0);
        write_Ref8U(safe_decode_range(ws['!ref'] || "A1"), o);
        o.write_shift(4, 4);
        write_biff_rec(ba, "Feat", o);
      }

      function write_CELLXFS_biff8(ba, opts) {
        for (var i = 0; i < 16; ++i) {
          write_biff_rec(ba, "XF", write_XF({
            numFmtId: 0,
            style: true
          }, 0, opts));
        }

        opts.cellXfs.forEach(function (c) {
          write_biff_rec(ba, "XF", write_XF(c, 0, opts));
        });
      }

      function write_ws_biff8_hlinks(ba, ws) {
        for (var R = 0; R < ws['!links'].length; ++R) {
          var HL = ws['!links'][R];
          write_biff_rec(ba, "HLink", write_HLink(HL));
          if (HL[1].Tooltip) write_biff_rec(ba, "HLinkTooltip", write_HLinkTooltip(HL));
        }

        delete ws['!links'];
      }

      function write_ws_biff8_cell(ba, cell, R, C, opts) {
        var os = 16 + get_cell_style(opts.cellXfs, cell, opts);

        if (cell.v == null && !cell.bf) {
          write_biff_rec(ba, "Blank", write_XLSCell(R, C, os));
          return;
        }

        if (cell.bf) write_biff_rec(ba, "Formula", write_Formula(cell, R, C, opts, os));else switch (cell.t) {
          case 'd':
          case 'n':
            var v = cell.t == 'd' ? datenum(parseDate(cell.v)) : cell.v;
            /* TODO: emit RK as appropriate */

            write_biff_rec(ba, "Number", write_Number(R, C, v, os, opts));
            break;

          case 'b':
          case 'e':
            write_biff_rec(ba, 0x0205, write_BoolErr(R, C, cell.v, os, opts, cell.t));
            break;

          /* TODO: codepage, sst */

          case 's':
          case 'str':
            write_biff_rec(ba, "Label", write_Label(R, C, cell.v, os, opts));
            break;

          default:
            write_biff_rec(ba, "Blank", write_XLSCell(R, C, os));
        }
      }
